#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int x1, y1, x2, y2;
} Rect;

static int *distances;
static int *heap;
static int *position;
static int heap_size;

static void sift_up(int i) {
    while (i > 0) {
        int p = (i - 1) / 2;
        if (distances[heap[p]] <= distances[heap[i]]) break;

        int a = heap[p], b = heap[i];
        heap[p] = b;
        heap[i] = a;
        position[a] = i;
        position[b] = p;
        i = p;
    }
}

static void sift_down(int i) {
    while (1) {
        int left = 2 * i + 1;
        int right = left + 1;
        int smallest = i;

        if (left < heap_size &&
            distances[heap[left]] < distances[heap[smallest]])
            smallest = left;
        if (right < heap_size &&
            distances[heap[right]] < distances[heap[smallest]])
            smallest = right;
        if (smallest == i) break;

        int a = heap[i], b = heap[smallest];
        heap[i] = b;
        heap[smallest] = a;
        position[a] = smallest;
        position[b] = i;
        i = smallest;
    }
}

static void relax(int v, int new_distance) {
    if (new_distance >= distances[v] || position[v] == -2) return;

    distances[v] = new_distance;
    if (position[v] == -1) {
        position[v] = heap_size;
        heap[heap_size++] = v;
    }
    sift_up(position[v]);
}

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

static int lower_bound_int(const int *a, int n, int value) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < value) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

