    int xi, yi, xf, yf;
    if (scanf("%d %d %d %d", &xi, &yi, &xf, &yf) != 4) return 0;

    int n;
    scanf("%d", &n);

    Rect rects[1000];
    int xs[2002], ys[2002];
    int x_count = 0, y_count = 0;

    xs[x_count++] = xi;
    xs[x_count++] = xf;
    ys[y_count++] = yi;
    ys[y_count++] = yf;

    for (int i = 0; i < n; ++i) {
        scanf("%d %d %d %d", &rects[i].x1, &rects[i].y1,
              &rects[i].x2, &rects[i].y2);
        xs[x_count++] = rects[i].x1;
        xs[x_count++] = rects[i].x2;
        ys[y_count++] = rects[i].y1;
        ys[y_count++] = rects[i].y2;
    }

    qsort(xs, x_count, sizeof(int), compare_ints);
    qsort(ys, y_count, sizeof(int), compare_ints);

    int nx = 0, ny = 0;
    for (int i = 0; i < x_count; ++i)
        if (nx == 0 || xs[i] != xs[nx - 1]) xs[nx++] = xs[i];
    for (int i = 0; i < y_count; ++i)
        if (ny == 0 || ys[i] != ys[ny - 1]) ys[ny++] = ys[i];

