    int finish = finish_y * nx + finish_x;

    heap_size = 0;
    distances[start] = 0;
    position[start] = heap_size;
    heap[heap_size++] = start;

    while (heap_size > 0) {
        int u = heap[0];
        int last = heap[--heap_size];
        position[u] = -2;

        if (heap_size > 0) {
            heap[0] = last;
            position[last] = 0;
            sift_down(0);
        }

        if (u == finish) break;

        int x = u % nx;
        int y = u / nx;
        int base = distances[u];

        if (x + 1 < nx) {
            int is_covered = horizontal_degenerate[(size_t)y * (nx - 1) + x];
            if (!is_covered) {
                if (y > 0 && covered[(size_t)(y - 1) * cell_width + x])
                    is_covered = 1;
                if (y < ny - 1 && covered[(size_t)y * cell_width + x])
                    is_covered = 1;
            }
            int cost = is_covered ? 0 : xs[x + 1] - xs[x];
            relax(u + 1, base + cost);
        }

        if (x > 0) {
            int is_covered = horizontal_degenerate[(size_t)y * (nx - 1) + x - 1];
            if (!is_covered) {
                if (y > 0 && covered[(size_t)(y - 1) * cell_width + x - 1])
                    is_covered = 1;
                if (y < ny - 1 && covered[(size_t)y * cell_width + x - 1])
                    is_covered = 1;
            }
            int cost = is_covered ? 0 : xs[x] - xs[x - 1];
            relax(u - 1, base + cost);
        }

        if (y + 1 < ny) {
            int is_covered = vertical_degenerate[(size_t)y * nx + x];
            if (!is_covered) {
                if (x > 0 && covered[(size_t)y * cell_width + x - 1])
                    is_covered = 1;
                if (x < nx - 1 && covered[(size_t)y * cell_width + x])
                    is_covered = 1;
            }
            int cost = is_covered ? 0 : ys[y + 1] - ys[y];
            relax(u + nx, base + cost);
        }

        if (y > 0) {
            int is_covered = vertical_degenerate[(size_t)(y - 1) * nx + x];
            if (!is_covered) {
                if (x > 0 && covered[(size_t)(y - 1) * cell_width + x - 1])
